mapper.select:
SELECT a.id, a.name, a.district_id, a.address_detail, a.min_lease_months, a.deposit_months, a.payment_method, a.publish_status, (SELECT COUNT(1) FROM rental_room r WHERE r.apartment_id = a.id AND r.is_delete = 0) AS room_count, (SELECT COUNT(1) FROM rental_room r WHERE r.apartment_id = a.id AND r.is_delete = 0 AND NOT EXISTS (SELECT 1 FROM rental_lease l WHERE l.room_id = r.id AND l.is_delete = 0 AND l.status IN (1, 2, 5))) AS vacant_room_count FROM rental_apartment a WHERE a.is_delete = 0
AND a.name LIKE CONCAT('%', #{query.name}, '%')
AND a.district_id = #{query.districtId}
AND a.payment_method = #{query.paymentMethod}
AND a.publish_status = #{query.publishStatus}
AND a.district_id IN
#{districtId}
ORDER BY a.id DESC

SELECT a.*
FROM rental_apartment a
WHERE a.is_delete = 0
  AND a.publish_status = 1

    AND a.district_id = #{query.districtId}


    AND a.district_id IN

        #{districtId}



    AND a.payment_method = #{query.paymentMethod}


    AND a.min_lease_months <= #{query.minLeaseMonths}


    AND EXISTS (SELECT 1
                FROM rental_room r
                WHERE r.apartment_id = a.id
                  AND r.is_delete = 0
                  AND r.publish_status = 1

        AND r.rent >= #{query.minRent}


        AND r.rent <= #{query.maxRent}


        AND r.room_count = #{query.roomCount}


        AND r.area >= #{query.minArea}


        AND r.area <= #{query.maxArea}

                )


    AND

        FIND_IN_SET(#{labelCode}, a.label_codes)


ORDER BY a.id DESC

SELECT r.apartment_id AS apartmentId, MIN(r.rent) AS minRent FROM rental_room r WHERE r.is_delete = 0 AND r.publish_status = 1 AND r.apartment_id IN
#{apartmentId}
GROUP BY r.apartment_id
